def countWildcardMatches(s, p):
    MOD = 10 ** 9 + 7
    n = len(p)
    prev = [0] * (n + 1)
    prev[0] = 1
    for j in range(1, n + 1):
        prev[j] = prev[j - 1] if p[j - 1] == '*' else 0
    for i in range(1, len(s) + 1):
        ch = s[i - 1]
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            c = p[j - 1]
            if c == '*':
                cur[j] = (cur[j - 1] + prev[j]) % MOD
            elif c == '?' or c == ch:
                cur[j] = prev[j - 1]
        prev = cur
    return prev[n]
